:root {
  color-scheme: light;
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  color: #241f1a;
  background: #fbfaf8;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  --background: #fbfaf8;
  --surface: #ffffff;
  --text: #241f1a;
  --muted: #716a62;
  --line: #ded9d2;
  --accent: #b95318;
  --focus: #1769aa;
}

:root[data-theme="dark"] {
  color-scheme: dark;
  color: #eeeae4;
  background: #121110;
  --background: #121110;
  --surface: #191816;
  --text: #eeeae4;
  --muted: #aaa39a;
  --line: #403c37;
  --accent: #ef8a4c;
  --focus: #75bfff;
}

* {
  box-sizing: border-box;
}

html {
  min-width: 320px;
  min-height: 100%;
  background: var(--background);
}

body {
  min-width: 320px;
  min-height: 100vh;
  margin: 0;
  color: var(--text);
  background: var(--background);
}

button,
a {
  font: inherit;
}

button:focus-visible,
a:focus-visible,
main:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 3px;
}

.skip-link {
  position: fixed;
  z-index: 10;
  top: 0.75rem;
  left: 0.75rem;
  padding: 0.65rem 0.8rem;
  color: var(--surface);
  background: var(--text);
  transform: translateY(-180%);
}

.skip-link:focus {
  transform: translateY(0);
}

.site-header {
  display: grid;
  grid-template-columns: minmax(12rem, 1fr) auto minmax(12rem, 1fr);
  align-items: center;
  min-height: 4.5rem;
  padding: 0 2.5rem;
  border-bottom: 1px solid var(--line);
  background: var(--surface);
}

.header-start {
  display: flex;
  gap: 0.75rem;
  align-items: center;
  min-width: 0;
}

.back-control {
  display: inline-grid;
  width: 2rem;
  height: 2rem;
  flex: 0 0 auto;
  place-items: center;
  padding: 0;
  border: 1px solid var(--accent);
  border-radius: 0.25rem;
  color: var(--accent);
  background: transparent;
  font-size: 1.2rem;
  font-weight: 700;
  line-height: 1;
  cursor: pointer;
}

.back-control:hover {
  color: var(--surface);
  background: var(--accent);
}

.brand {
  display: flex;
  gap: 0.65rem;
  align-items: center;
  min-width: 0;
  font-weight: 650;
}

.brand-mark {
  display: inline-grid;
  width: 1.8rem;
  height: 1.8rem;
  flex: 0 0 auto;
  place-items: center;
  border: 1px solid var(--accent);
  border-radius: 50%;
  color: var(--accent);
  font-size: 0.8rem;
}

nav {
  display: flex;
  gap: 0.35rem;
}

.nav-link {
  padding: 0.55rem 0.8rem;
  border-radius: 0.25rem;
  color: var(--muted);
  text-decoration: none;
}

.nav-link:hover,
.nav-link.active {
  color: var(--text);
  background: color-mix(in srgb, var(--accent) 10%, transparent);
}

.theme-toggle {
  justify-self: end;
  padding: 0.5rem 0.7rem;
  border: 1px solid var(--line);
  border-radius: 0.25rem;
  color: var(--text);
  background: transparent;
  cursor: pointer;
}

.site-main {
  min-height: calc(100vh - 4.5rem);
  padding: clamp(3rem, 8vw, 8rem) max(2rem, 8vw);
}

.shell-state,
.placeholder {
  max-width: 48rem;
}

.eyebrow {
  margin: 0 0 0.85rem;
  color: var(--accent);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

h1 {
  margin: 0 0 1rem;
  font-size: clamp(2rem, 4vw, 3.75rem);
  font-weight: 520;
  letter-spacing: -0.035em;
}

p,
li {
  color: var(--muted);
  line-height: 1.65;
}

.shell-error button {
  margin-top: 1rem;
  padding: 0.65rem 0.85rem;
  border: 1px solid var(--text);
  border-radius: 0.25rem;
  color: var(--surface);
  background: var(--text);
  cursor: pointer;
}

.diagnostic-code,
code {
  font-family: "SFMono-Regular", Consolas, "Liberation Mono", monospace;
  font-size: 0.9em;
}

@media (max-width: 760px) {
  .site-header {
    grid-template-columns: 1fr auto;
    gap: 0.75rem;
    padding: 0.85rem 1rem;
  }

  nav {
    grid-column: 1 / -1;
    grid-row: 2;
    overflow-x: auto;
  }

  .theme-toggle {
    grid-column: 2;
    grid-row: 1;
  }

  .site-main {
    padding: 3rem 1.25rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
  }
}

